private fun icon(name: String, vararg paths: String): ImageVector = icon(name, autoMirror = false, paths = paths)

/** [autoMirror] flips the icon in right-to-left layouts (arrows and carets). */
private fun icon(name: String, autoMirror: Boolean, paths: Array<out String>): ImageVector =
    ImageVector.Builder("Phosphor.$name", 24.dp, 24.dp, viewportWidth = 256f, viewportHeight = 256f, autoMirror = autoMirror).apply {
        for (d in paths) addPath(PathParser().parsePathString(d).toNodes(), fill = SolidColor(Color.Black))
    }.build()
